-- Touchline 2026/27 snapshot seed. Generated from ESPN's public soccer API.
-- Idempotent for leagues, seasons, teams, venues, players and fixtures.
-- Run after schema-oracle.sql while connected as the oracle application user.
-- Fixture timestamps are stored as UTC in Oracle TIMESTAMP (no timezone).
SET FEEDBACK OFF
SET DEFINE OFF

MERGE INTO countries c USING (SELECT 'England' name FROM dual) x ON (UPPER(c.name)=UPPER(x.name)) WHEN NOT MATCHED THEN INSERT (name) VALUES (x.name);
MERGE INTO countries c USING (SELECT 'France' name FROM dual) x ON (UPPER(c.name)=UPPER(x.name)) WHEN NOT MATCHED THEN INSERT (name) VALUES (x.name);
MERGE INTO countries c USING (SELECT 'Germany' name FROM dual) x ON (UPPER(c.name)=UPPER(x.name)) WHEN NOT MATCHED THEN INSERT (name) VALUES (x.name);
MERGE INTO countries c USING (SELECT 'Italy' name FROM dual) x ON (UPPER(c.name)=UPPER(x.name)) WHEN NOT MATCHED THEN INSERT (name) VALUES (x.name);
MERGE INTO countries c USING (SELECT 'Spain' name FROM dual) x ON (UPPER(c.name)=UPPER(x.name)) WHEN NOT MATCHED THEN INSERT (name) VALUES (x.name);

MERGE INTO leagues l USING (SELECT 'Premier League' name, country_id FROM countries WHERE UPPER(name)=UPPER('England')) x ON (UPPER(l.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET l.country_id=x.country_id WHEN NOT MATCHED THEN INSERT (name,country_id) VALUES (x.name,x.country_id);
MERGE INTO leagues l USING (SELECT 'LaLiga' name, country_id FROM countries WHERE UPPER(name)=UPPER('Spain')) x ON (UPPER(l.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET l.country_id=x.country_id WHEN NOT MATCHED THEN INSERT (name,country_id) VALUES (x.name,x.country_id);
MERGE INTO leagues l USING (SELECT 'Serie A' name, country_id FROM countries WHERE UPPER(name)=UPPER('Italy')) x ON (UPPER(l.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET l.country_id=x.country_id WHEN NOT MATCHED THEN INSERT (name,country_id) VALUES (x.name,x.country_id);
MERGE INTO leagues l USING (SELECT 'Ligue 1' name, country_id FROM countries WHERE UPPER(name)=UPPER('France')) x ON (UPPER(l.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET l.country_id=x.country_id WHEN NOT MATCHED THEN INSERT (name,country_id) VALUES (x.name,x.country_id);
MERGE INTO leagues l USING (SELECT 'Bundesliga' name, country_id FROM countries WHERE UPPER(name)=UPPER('Germany')) x ON (UPPER(l.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET l.country_id=x.country_id WHEN NOT MATCHED THEN INSERT (name,country_id) VALUES (x.name,x.country_id);

MERGE INTO seasons se USING (SELECT league_id FROM leagues WHERE UPPER(name)=UPPER('Premier League') AND country_id=(SELECT country_id FROM countries WHERE UPPER(name)=UPPER('England'))) x ON (se.league_id=x.league_id AND se.label='2026/27') WHEN MATCHED THEN UPDATE SET se.start_date=TO_DATE('2026-08-21','YYYY-MM-DD'), se.end_date=TO_DATE('2027-05-30','YYYY-MM-DD') WHEN NOT MATCHED THEN INSERT (league_id,label,start_date,end_date) VALUES (x.league_id,'2026/27',TO_DATE('2026-08-21','YYYY-MM-DD'),TO_DATE('2027-05-30','YYYY-MM-DD'));
MERGE INTO seasons se USING (SELECT league_id FROM leagues WHERE UPPER(name)=UPPER('LaLiga') AND country_id=(SELECT country_id FROM countries WHERE UPPER(name)=UPPER('Spain'))) x ON (se.league_id=x.league_id AND se.label='2026/27') WHEN MATCHED THEN UPDATE SET se.start_date=TO_DATE('2026-08-15','YYYY-MM-DD'), se.end_date=TO_DATE('2027-05-30','YYYY-MM-DD') WHEN NOT MATCHED THEN INSERT (league_id,label,start_date,end_date) VALUES (x.league_id,'2026/27',TO_DATE('2026-08-15','YYYY-MM-DD'),TO_DATE('2027-05-30','YYYY-MM-DD'));
MERGE INTO seasons se USING (SELECT league_id FROM leagues WHERE UPPER(name)=UPPER('Serie A') AND country_id=(SELECT country_id FROM countries WHERE UPPER(name)=UPPER('Italy'))) x ON (se.league_id=x.league_id AND se.label='2026/27') WHEN MATCHED THEN UPDATE SET se.start_date=TO_DATE('2026-08-22','YYYY-MM-DD'), se.end_date=TO_DATE('2027-05-30','YYYY-MM-DD') WHEN NOT MATCHED THEN INSERT (league_id,label,start_date,end_date) VALUES (x.league_id,'2026/27',TO_DATE('2026-08-22','YYYY-MM-DD'),TO_DATE('2027-05-30','YYYY-MM-DD'));
MERGE INTO seasons se USING (SELECT league_id FROM leagues WHERE UPPER(name)=UPPER('Ligue 1') AND country_id=(SELECT country_id FROM countries WHERE UPPER(name)=UPPER('France'))) x ON (se.league_id=x.league_id AND se.label='2026/27') WHEN MATCHED THEN UPDATE SET se.start_date=TO_DATE('2026-08-21','YYYY-MM-DD'), se.end_date=TO_DATE('2027-05-29','YYYY-MM-DD') WHEN NOT MATCHED THEN INSERT (league_id,label,start_date,end_date) VALUES (x.league_id,'2026/27',TO_DATE('2026-08-21','YYYY-MM-DD'),TO_DATE('2027-05-29','YYYY-MM-DD'));
MERGE INTO seasons se USING (SELECT league_id FROM leagues WHERE UPPER(name)=UPPER('Bundesliga') AND country_id=(SELECT country_id FROM countries WHERE UPPER(name)=UPPER('Germany'))) x ON (se.league_id=x.league_id AND se.label='2026/27') WHEN MATCHED THEN UPDATE SET se.start_date=TO_DATE('2026-08-28','YYYY-MM-DD'), se.end_date=TO_DATE('2027-05-22','YYYY-MM-DD') WHEN NOT MATCHED THEN INSERT (league_id,label,start_date,end_date) VALUES (x.league_id,'2026/27',TO_DATE('2026-08-28','YYYY-MM-DD'),TO_DATE('2027-05-22','YYYY-MM-DD'));

