MERGE INTO teams t USING (SELECT 'AFC Bournemouth' name, (SELECT l.league_id FROM leagues l JOIN countries c ON c.country_id=l.country_id WHERE UPPER(l.name)=UPPER('Premier League') AND UPPER(c.name)=UPPER('England')) league_id, (SELECT stadium_id FROM stadiums WHERE UPPER(name)=UPPER('Vitality Stadium')) stadium_id FROM dual) x ON (UPPER(t.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET t.league_id=x.league_id, t.stadium_id=x.stadium_id WHEN NOT MATCHED THEN INSERT (name,league_id,stadium_id) VALUES (x.name,x.league_id,x.stadium_id);
