MERGE INTO players p USING (SELECT team_id, 'Fraser Forster' name FROM teams WHERE UPPER(name)=UPPER('AFC Bournemouth')) x ON (p.team_id=x.team_id AND UPPER(p.name)=UPPER(x.name)) WHEN MATCHED THEN UPDATE SET p.date_of_birth=TO_DATE('1988-03-17','YYYY-MM-DD'), p.nationality='England', p.position='Goalkeeper', p.height_cm=200.66, p.jersey_no=17 WHEN NOT MATCHED THEN INSERT (team_id,name,date_of_birth,nationality,position,height_cm,jersey_no) VALUES (x.team_id,x.name,TO_DATE('1988-03-17','YYYY-MM-DD'),'England','Goalkeeper',200.66,17);
