MERGE INTO matches m USING (SELECT (SELECT season_id FROM seasons se JOIN leagues l ON l.league_id=se.league_id JOIN countries c ON c.country_id=l.country_id WHERE UPPER(l.name)=UPPER('LaLiga') AND UPPER(c.name)=UPPER('Spain') AND se.label='2026/27') season_id, (SELECT team_id FROM teams WHERE UPPER(name)=UPPER('Alavés')) home_id, (SELECT team_id FROM teams WHERE UPPER(name)=UPPER('Getafe')) away_id, (SELECT stadium_id FROM stadiums WHERE UPPER(name)=UPPER('Mendizorrotza')) stadium_id, TO_TIMESTAMP('2026-08-15 17:30:00','YYYY-MM-DD HH24:MI:SS') match_date FROM dual) x ON (m.season_id=x.season_id AND m.match_date=x.match_date AND m.home_team_id=x.home_id AND m.away_team_id=x.away_id) WHEN MATCHED THEN UPDATE SET m.stadium_id=x.stadium_id, m.status='Completed', m.home_goals=3, m.away_goals=0 WHEN NOT MATCHED THEN INSERT (season_id,stadium_id,home_team_id,away_team_id,match_date,status,home_goals,away_goals) VALUES (x.season_id,x.stadium_id,x.home_id,x.away_id,x.match_date,'Completed',3,0);
